<section class="content-header"><h1>Nuevo proyecto inmobiliario</h1></section><section class="content"><div class="box box-primary"><form method="post" action="<?php echo site_url('proyecto/guardar'); ?>"><div class="box-body"><div class="form-group"><label>Nombre</label><input class="form-control" name="proyecto_nombre" required></div><div class="form-group"><label>Descripción</label><textarea class="form-control" name="proyecto_descripcion"></textarea></div><div class="row"><div class="col-md-6"><label>Categoría para los productos/lotes</label><select class="form-control" name="categoria_id" required><?php foreach($categorias as $c){ ?><option value="<?php echo $c['categoria_id']; ?>"><?php echo html_escape($c['categoria_nombre']); ?></option><?php } ?></select></div><div class="col-md-6"><label>Moneda</label><select class="form-control" name="moneda_id" required><?php foreach($monedas as $m){ ?><option value="<?php echo $m['moneda_id']; ?>"><?php echo html_escape($m['moneda_descripcion']); ?></option><?php } ?></select></div></div><input type="hidden" name="imagen_ancho" value="1200"><input type="hidden" name="imagen_alto" value="800"></div><div class="box-footer"><button class="btn btn-primary">Guardar</button> <a class="btn btn-default" href="<?php echo site_url('proyecto'); ?>">Cancelar</a></div></form></div></section>